import React, { useContext } from 'react'
import { Link } from 'react-router-dom'
import { apiValue } from "../AllData/AllData";
import { CartProvider, useCart } from "react-use-cart";


function LatestProducts() {

   const data = useContext(apiValue);
  const {addItem} =useCart();
  
  return (
    <div className="latest-products">
      <div className="container">
        <div className="row">


          <div className="col-md-12">
            <div className="section-heading">
              <h2>Latest Products</h2>
              <Link to="/product">
                view all products <i className="fa fa-angle-right"></i>
              </Link>
            </div>
          </div>

       {data.map((item) => {
            return item.id<7? (
              <div key={item.id} className="col-md-4 text-center mb-4">
                <div className="card p-3 w-100 ">
                  <img
                    src={item.image}
                    alt={item.title}
                    className="w-100 img-fluid"
                    style={{
                      height: "550px",
                      // objectFit: "cover",
                    }}
                  />
                  <h4>{item.title}</h4>
                  <h4>{item.id}</h4>
                  <p>${item.price}</p>
                  <div className="d-grid gap-2 mt-3">
                    <Link to={`/product/${item.id}`}>
                      <button className="btn btn-danger mx-1">Details</button>
                    </Link>

                    <button onClick={()=>{addItem(item)}} className="btn btn-danger">Add To Cart</button>
                  </div>


                </div>
              </div>
            ):null
          }
        )
      }
        
          


         

        </div>
      </div>
    </div>
  
  )
}

export default LatestProducts