import React, { useContext } from "react";
import { Link, useParams } from "react-router-dom";
import { apiValue } from "../AllData/AllData";
import Header from "../Home/Header";
import Footer from "../Home/Footer";
import { useCart } from "react-use-cart";
function SingleProduct(){
    const {addItem} =useCart();

   const data =useContext(apiValue);
   const {id}=useParams();
    const productId = data.find((item) => item.id === Number(id));
   
      if (!productId) {
    return <p className="text-center mt-5">Product not found</p>;
  }

  return (
    <div>
      <Header />

      <div className="container mt-5">
        <div className="row ">
          <div className="col-md-6">
            <img
              src={productId.image}
              alt={productId.title}
              className="w-75"
              style={{ height: 500, objectFit: "contain" }}
            />
          </div>

          <div className="col-md-6">
            <h2>{productId.title}</h2>
            <h4 className="text-danger">${productId.price}</h4>
            <p>{productId.description}</p>
            <p><strong>Category:</strong> {productId.category}</p>
            <Link to="/product" >
             <button
       className="btn mt-3 mx-3"
              style={{ backgroundColor: "#f33f3f", color: "#fff" }}
  >
   Back
  </button>
            </Link>
            <button onClick={()=>{addItem(productId)}} className="btn btn-danger mt-3 mx-3">Add To Cart</button>

          </div>
        </div>
      </div>
      <Footer/>
      </div>
  )

}

export default SingleProduct;