import React from "react";
import { CartProvider, useCart } from "react-use-cart";
import Header from "../Home/Header";
import Footer from "../Home/Footer";
import { Link } from "react-router";

function Cart() {
  const {
    items,
    updateItemQuantity,
    removeItem,
    totalItems,
    cartTotal,
    totalUniqueItems,
    emptyCart,
    isEmpty,
  } = useCart(); // ✅ الصح
  if (isEmpty) {
    return (
      <div className="  text-center col-md-10">
        <img src="/assets/images/cart.jpg" alt="Cart" style={{width:"300px"}}/>
        <h3>Your Cart is Empty</h3>
        <h4>
          <Link to="/product">
            <button className="btn btn-primary mt-2 "> Shoping</button>
          </Link>
        </h4>
      </div>
    );
  }

  return (
    <div>
      <div className="container">
        <div className="row">
          <div className="col-md-10 m-auto">
            <h3 className="text-center my-4">
              Daitails Of Products{" "}
              <span className="badge badge-primary">{totalUniqueItems}</span>
              <button
                onClick={() => {
                  emptyCart();
                }}
                className="btn btn-danger mx-2"
              >
                Empty Cart
              </button>
            </h3>
            <table className="table table-dark text-center">
              <thead>
                <tr>
                  <th>Image</th>
                  <th>ID</th>
                  <th>Name</th>
                  <th>Quantity</th>
                  <th>Price</th>
                  <th>Opreation</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => (
                  <tr key={item.id}>
                    <td>
                      <img
                        src={item.image}
                        alt={item.title}
                        className="w-100"
                        style={{ height: "250px" }}
                      />
                    </td>
                    <td className="mt-8">{item.id}</td>
                    <td className="text-center">{item.title}</td>
                    <td>{item.quantity}</td>
                    <td>{Math.ceil(item.price * item.quantity)}$</td>
                    <td>
                      <button
                        onClick={() => {
                          updateItemQuantity(item.id, item.quantity - 1);
                        }}
                        className="btn btn-warning"
                      >
                        -
                      </button>
                      <button
                        onClick={() => {
                          updateItemQuantity(item.id, item.quantity + 1);
                        }}
                        className="btn mx-2 btn-success"
                      >
                        +
                      </button>
                      <button
                        onClick={() => {
                          removeItem(item.id);
                        }}
                        className="btn btn-danger "
                      >
                        &times;
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr>
                  <td>Total</td>
                  <td>----------</td>
                  <td>----------</td>
                  <td>{totalItems}</td>
                  <td>{Math.ceil(cartTotal)}$</td>

                  <td>
                    <Link to="/product">
                      <button className="btn btn-primary">
                        Contuinue Shoping
                      </button>
                    </Link>
                  </td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

function AllCart() {
  return (
    <div>
      <Header />
      <br />
      <br />
      <Cart />
      <br />
      <br />
      <Footer />
    </div>
  );
}

export default AllCart;
