import React, { useContext, useState } from "react";
import { apiValue } from "../AllData/AllData";
import Header from "../Home/Header";
import Footer from "../Home/Footer";
import { Link } from "react-router";
import { CartProvider, useCart } from "react-use-cart";

function Page(){
  const data = useContext(apiValue);
  const {addItem} =useCart();
  const [search, setSearch] = useState("");
  const getData = (event) => {
    setSearch(event.target.value);
    console.log(event.target.value);
  };
  if (!Array.isArray(data)) return <p>Loading...</p>;
  return(
    <div>

      <div className="products container">
        <input
          placeholder="Search"
          className="form-control w-100 my-5"
          onChange={getData}
        ></input>
        <div className="row">
          {data.map((item) => {
            return search == "" ? (
              <div key={item.id} className="col-md-4 text-center mb-4">
                <div className="card p-3 w-100 ">
                  <img
                    src={item.image}
                    alt={item.title}
                    className="w-100 img-fluid"
                    style={{
                      height: "550px",
                      // objectFit: "cover",
                    }}
                  />
                  <h4>{item.title}</h4>
                  <h4>{item.id}</h4>
                  <p>${item.price}</p>
                  <div className="d-grid gap-2 mt-3">
                    <Link to={`/product/${item.id}`}>
                      <button className="btn btn-danger mx-1">Details</button>
                    </Link>

                    <button onClick={()=>{addItem(item)}} className="btn btn-danger">Add To Cart</button>
                  </div>
                </div>
              </div>
            ) : item.id == search ? (
              <div key={item.id} className="col-md-4 text-center mb-4">
                <div className="card p-3 w-100 ">
                  <img
                    src={item.image}
                    alt={item.title}
                    className="w-100 img-fluid"
                    style={{ height: "550px" }}
                  ></img>
                  <h4>{item.title}</h4>
                  <h4>{item.id}</h4>
                  <p>${item.price}</p>
                  <div className="d-grid gap-2 mt-3">

                  <Link to={`/product/${item.id}`}>
                    <button
                      className="btn  mx-1"
                      style={{ backgroundColor: "#f33f3f", color: "#fff" }}
                    >
                      Details
                    </button>
                  </Link>
                    <button onClick={()=>{addItem(item)}} className="btn btn-danger">Add To Cart</button>
                
                  </div>
                
                </div>
              </div>
            )  : item.title.toLowerCase().indexOf( search.toLocaleLowerCase())!=-1 ? (
              <div key={item.id} className="col-md-4 text-center mb-4">
                <div className="card p-3 w-100 ">
                  <img
                    src={item.image}
                    alt={item.title}
                    className="w-100 img-fluid"
                    style={{ height: "550px" }}
                  ></img>
                  <h4>{item.title}</h4>
                  <h4>{item.id}</h4>
                  <p>${item.price}</p>
                  <div className="d-grid gap-2 mt-3">

                  <Link to={`/product/${item.id}`}>
                    <button
                      className="btn mx-1"
                      style={{ backgroundColor: "#f33f3f", color: "#fff" }}
                    >
                      Details
                    </button>
                  </Link>
                     <button
  onClick={() => {
    addItem(item);
  }}
  className="btn btn-danger"
>
  Add To Cart
</button>
                  </div>

                </div>
              </div>
            ) : null;
          })}
        </div>
      </div>


    </div>
  )
          

}

function AllProduct() {
 

  return (
    <div>
      <Header />
      <Page />
      <Footer />
    </div>
  );
}

export default AllProduct ;
